-- ===================================================
-- Initialisation de la base de données sur Postgres
-- ===================================================

-- 1) Création des tables
CREATE TABLE P17_Epreuves (
                              EpreuveID SERIAL PRIMARY KEY,
                              EpreuveDistance VARCHAR(50) CHECK (EpreuveDistance IN ('50m', '100m', '200m', '400m', '800m', '1500m', '4 x 100m', '4 x 200m')),
                              EpreuveType VARCHAR(100) CHECK (EpreuveType IN ('nage libre', 'papillon', 'dos', 'brasse', 'quatre nages')),
                              EpreuveCategorie CHAR(1) CHECK (EpreuveCategorie IN ('H', 'F', 'M')),
                              EpreuveTour VARCHAR(50) CHECK (EpreuveTour IN (
                                                                             'Serie 1', 'Serie 2', 'Serie 3', 'Serie 4', 'Serie 5',
                                                                             'Serie 6', 'Serie 7', 'Serie 8', 'Serie 9', 'Serie 10',
                                                                             'Demi-finale 1', 'Demi-finale 2', 'Finale', 'Demi-finale Barrage'
                                  )),
                              EpreuveDate DATE,
                              EpreuveHeure TIME
);

CREATE TABLE P17_Nageurs (
                             NageurID SERIAL PRIMARY KEY,
                             NageurNom VARCHAR(50),
                             NageurPrenom VARCHAR(50),
                             NageurSexe CHAR(1) CHECK (NageurSexe IN ('H', 'F')),
                             NageurPays CHAR(3),
                             NageurDateNaissance DATE
);

CREATE TABLE P17_RelaisEquipe (
                                  RelaisEquipeID SERIAL PRIMARY KEY,
                                  RelaisEquipePays CHAR(3)
);

CREATE TABLE P17_ComposerEquipe (
                                    RelaisEquipeID INT REFERENCES P17_RelaisEquipe(RelaisEquipeID) ON DELETE CASCADE,
                                    NageurID INT REFERENCES P17_Nageurs(NageurID) ON DELETE CASCADE,
                                    PRIMARY KEY (RelaisEquipeID, NageurID)
);

CREATE TABLE P17_ParticiperEquipe (
                                      RelaisEquipeID INT REFERENCES P17_RelaisEquipe(RelaisEquipeID) ON DELETE CASCADE,
                                      EpreuveID INT REFERENCES P17_Epreuves(EpreuveID) ON DELETE CASCADE,
                                      Position INT,
                                      Temps VARCHAR(10),
                                      Couloir INT,
                                      Medaille VARCHAR(10) CHECK (Medaille IN ('Or', 'Argent', 'Bronze', 'Aucune')),
                                      PRIMARY KEY (RelaisEquipeID, EpreuveID)
);

CREATE TABLE P17_ParticiperIndividuel (
                                          NageurID INT REFERENCES P17_Nageurs(NageurID) ON DELETE CASCADE,
                                          EpreuveID INT REFERENCES P17_Epreuves(EpreuveID) ON DELETE CASCADE,
                                          Position INT,
                                          Temps VARCHAR(10),
                                          Couloir INT,
                                          Medaille VARCHAR(10) CHECK (Medaille IN ('Or', 'Argent', 'Bronze', 'Aucune')),
                                          PRIMARY KEY (NageurID, EpreuveID)
);

-- Tables utilisées par les triggers
-- Table utilisée par le trigger P17_Trigger_UpdateTotalNageurs
CREATE TABLE IF NOT EXISTS P17_Statistiques (
                                                StatID INT PRIMARY KEY DEFAULT 1,
                                                NbTotalNageurs INT
);

-- Table utilisée par le trigger P17_Trigger_LogModifications
CREATE TABLE IF NOT EXISTS P17_HistoriqueModifications (
                                                           HistoriqueID SERIAL PRIMARY KEY,
                                                           OperationType VARCHAR(10),     -- Type d'opération (INSERT, UPDATE, DELETE)
                                                           NageurID INT,                  -- L'identifiant du nageur impacté
                                                           EpreuveID INT,                 -- L'épreuve associée
                                                           DateModification TIMESTAMP,    -- Date de la modification
                                                           ValeursAnciennes JSONB,        -- Anciennes valeurs (pour UPDATE/DELETE)
                                                           ValeursNouvelles JSONB         -- Nouvelles valeurs (pour INSERT/UPDATE)
);

-- 2) Création des VUES
-- Vue des médailles par nageur
CREATE VIEW P17_Vue_MedaillesNageur AS
SELECT
    N.NageurNom,
    N.NageurPrenom,
    N.NageurPays,
    COUNT(CASE WHEN PI.Medaille = 'Or' THEN 1 END) AS Nb_Or,
    COUNT(CASE WHEN PI.Medaille = 'Argent' THEN 1 END) AS Nb_Argent,
    COUNT(CASE WHEN PI.Medaille = 'Bronze' THEN 1 END) AS Nb_Bronze
FROM
    P17_Nageurs N
        JOIN P17_ParticiperIndividuel PI ON N.NageurID = PI.NageurID
GROUP BY
    N.NageurNom, N.NageurPrenom, N.NageurPays;

-- Vue des résultats des épreuves par date
CREATE VIEW P17_Vue_CalendrierEpreuves AS
SELECT
    E.EpreuveDate,
    E.EpreuveDistance,
    E.EpreuveType,
    E.EpreuveTour,
    PI.Position,
    N.NageurNom,
    N.NageurPrenom,
    PI.Temps
FROM
    P17_Epreuves E
        JOIN P17_ParticiperIndividuel PI ON E.EpreuveID = PI.EpreuveID
        JOIN P17_Nageurs N ON N.NageurID = PI.NageurID
ORDER BY
    E.EpreuveDate, E.EpreuveDistance, PI.Position;

-- Vue des équipes gagnantes
CREATE VIEW P17_Vue_EquipesGagnantes AS
SELECT
    E.EpreuveDate,
    E.EpreuveDistance,
    E.EpreuveType,
    E.EpreuveTour,
    PE.Medaille,
    RE.RelaisEquipePays
FROM
    P17_Epreuves E
        JOIN P17_ParticiperEquipe PE ON E.EpreuveID = PE.EpreuveID
        JOIN P17_RelaisEquipe RE ON RE.RelaisEquipeID = PE.RelaisEquipeID
WHERE
    PE.Medaille IN ('Or', 'Argent', 'Bronze');

-- 3) Création des FONCTIONS et PROCEDURES

-- Procédure qui met à jour le temps d'une participation individuelle.
CREATE OR REPLACE PROCEDURE P17_Proc_UpdateTemps(NagID INT, IDEpreuve INT, NouveauTemps VARCHAR(10))
AS $$
BEGIN
    UPDATE P17_ParticiperIndividuel
    SET Temps = NouveauTemps
    WHERE NageurID = NagID AND EpreuveID = IDEpreuve;
EXCEPTION
    WHEN OTHERS THEN
        RAISE NOTICE 'Erreur lors de la mise à jour du temps pour NageurID = %, EpreuveID = %', NagID, IDEpreuve;
END;
$$ LANGUAGE plpgsql;








-- Fonction qui retourne le nombre total de médailles d'or gagnées par un nageur donné
CREATE OR REPLACE FUNCTION P17_Func_MedaillesOr(NagID INT)
    RETURNS INT AS
$$
DECLARE
    total_or INT;
BEGIN
    SELECT COUNT(*) INTO total_or
    FROM P17_ParticiperIndividuel
    WHERE NageurID = NagID AND Medaille = 'Or';
    RETURN total_or;
END;
$$ LANGUAGE plpgsql;

-- Fonction qui retourne la liste des épreuves où un nageur a obtenu une médaille d'or.
CREATE OR REPLACE FUNCTION P17_Func_EpreuvesOr(NagID INT)
    RETURNS TABLE(EpreuveID INT, EpreuveDistance VARCHAR ,EpreuveType VARCHAR, EpreuveDate DATE)
AS
$$
BEGIN
    RETURN QUERY
        SELECT E.EpreuveID, E.EpreuveDistance ,E.EpreuveType, E.EpreuveDate
        FROM P17_ParticiperIndividuel PI
                 JOIN P17_Epreuves E ON E.EpreuveID = PI.EpreuveID
        WHERE PI.NageurID = NagID AND PI.Medaille = 'Or';
END;
$$ LANGUAGE plpgsql;

-- Procédure qui affiche les nageurs ayant obtenu une médaille dans les épreuves individuelles.
CREATE OR REPLACE PROCEDURE P17_Proc_AfficheGagnantMedaille()
AS $$
DECLARE
    cur CURSOR FOR
        SELECT DISTINCT N.NageurNom, N.NageurPrenom
        FROM P17_Nageurs N
                 JOIN P17_ParticiperIndividuel PI ON N.NageurID = PI.NageurID
        WHERE PI.Medaille = 'Or' OR PI.Medaille = 'Argent' OR PI.Medaille = 'Bronze';
    record RECORD;
BEGIN
    FOR record IN cur LOOP
            RAISE NOTICE 'Nageur: % %', record.NageurNom, record.NageurPrenom;
        END LOOP;
END;
$$ LANGUAGE plpgsql;

-- Fonctions et procédures spéciales pour les triggers
-- Fonction utilisée par le trigger P17_Trigger_UpdateTotalNageurs
CREATE OR REPLACE FUNCTION P17_Func_UpdateTotalNageurs()
    RETURNS TRIGGER AS $$
BEGIN
    -- Met à jour le total des nageurs dans la table P17_Statistiques
    UPDATE P17_Statistiques
    SET NbTotalNageurs = (SELECT COUNT(*) FROM P17_Nageurs)
    WHERE StatID = 1;

    -- Insérer la ligne si elle n'existe pas
    VALUES (1, (SELECT COUNT(*) FROM P17_Nageurs))
    ON CONFLICT (StatID) DO NOTHING;

    RETURN NULL;  -- Ce trigger ne modifie pas les lignes
END;
$$ LANGUAGE plpgsql;

-- Fonction utilisée par le trigger P17_Trigger_LogModifications
CREATE OR REPLACE FUNCTION P17_Func_LogModifications()
    RETURNS TRIGGER AS $$
BEGIN
    -- Insérer dans la table P17_HistoriqueModifications
        OperationType,
        NageurID,
        EpreuveID,
        DateModification,
        ValeursAnciennes,
        ValeursNouvelles
    )
    VALUES (
               TG_OP,  -- Type d'opération (INSERT, UPDATE, DELETE)
               COALESCE(OLD.NageurID, NEW.NageurID),
               COALESCE(OLD.EpreuveID, NEW.EpreuveID),
               CURRENT_TIMESTAMP,
               TO_JSONB(OLD),
               TO_JSONB(NEW)
           );

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- 4) Création des TRIGGERS

-- Trigger qui met à jour automatiquement le total des nageurs dans P17_Statistiques après chaque insertion ou suppression.
CREATE TRIGGER P17_Trigger_UpdateTotalNageurs
    AFTER INSERT OR DELETE
    ON P17_Nageurs
    FOR EACH STATEMENT
EXECUTE FUNCTION P17_Func_UpdateTotalNageurs();

-- Trigger qui enregistre les modifications (INSERT, UPDATE, DELETE) dans P17_HistoriqueModifications pour assurer une traçabilité.
CREATE TRIGGER P17_Trigger_LogModifications
    AFTER INSERT OR UPDATE OR DELETE
    ON P17_ParticiperIndividuel
    FOR EACH ROW
EXECUTE FUNCTION P17_Func_LogModifications();

-- 5) Message de confirmation
DO $$
    BEGIN
        RAISE NOTICE 'Base de données initialisée avec succès ! Toutes les tables, séquences, vues, procédures, fonctions et triggers ont été créés.';
    END $$;
